src/layouts/Layout.astro:
---
import data from '../data.json';
import '../global.css';
---
<html lang="fa"><head><meta charset="utf-8"/><title>{data.title}</title></head><body><nav><a href="/">Home</a><a href="/about/">About</a></nav><slot /></body></html>

src/pages/index.astro:
---
import Layout from '../layouts/Layout.astro';
import Card from '../components/Card.astro';
import data from '../data.json';
---
<Layout><Card title={data.title}/><button id="demo">Ready</button><script>document.querySelector('#demo')?.addEventListener('click', e => e.target.textContent = 'Clicked');</script></Layout>

src/pages/about.astro:
---
import Layout from '../layouts/Layout.astro';
import data from '../data.json';
---
<Layout><h1>About {data.title}</h1></Layout>
